SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
SET TIME_ZONE = '+00:00';

CREATE TABLE `users` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `identifiant` VARCHAR(255) NOT NULL,
  `password` VARCHAR(255) NOT NULL,
  `token` TEXT NOT NULL,
  `type` TEXT NOT NULL,
  `user_id` INT DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Structure de la table `client`
--

CREATE TABLE `client` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `user_id` INT DEFAULT NULL,
  `name` TEXT NOT NULL,
  `email` TEXT NOT NULL,
  `tel` TEXT NOT NULL,
  `adress` TEXT NOT NULL,
  `note` TEXT DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Structure de la table `atelier_type`
--

CREATE TABLE `atelier_type` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `name` TEXT NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Structure de la table `praticien`
--

CREATE TABLE `praticien` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `user_id` INT DEFAULT NULL,
  `name` TEXT NOT NULL,
  `surname` TEXT NOT NULL,
  `email` TEXT NOT NULL,
  `tel` TEXT NOT NULL,
  `siret` TEXT NOT NULL,
  `siret_justificatif` LONGBLOB NOT NULL,
  `assurance` TEXT NOT NULL,
  `assurance_date` DATE DEFAULT NULL,
  `assurance_justificatif` LONGBLOB NOT NULL,
  `state` TEXT NOT NULL,
  `created_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Structure de la table `atelier`
--

CREATE TABLE `atelier` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `type` VARCHAR(255) NOT NULL,
  `date_hours` DATETIME NOT NULL,
  `duration` TIME NOT NULL,
  `state` VARCHAR(255) NOT NULL,
  `max_participants` INT NOT NULL,
  `participants` INT DEFAULT NULL,
  `praticien_id` INT DEFAULT NULL,
  `client_id` INT NOT NULL,
  `created_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Structure de la table `participation_atelier`
--

CREATE TABLE `participation_atelier` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `atelier_id` INT NOT NULL,
  `praticien_id` INT NOT NULL,
  `state` TEXT NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Structure de la table `praticien_justificatif`
--

CREATE TABLE `praticien_justificatif` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `praticien_id` INT NOT NULL,
  `pratique` VARCHAR(255) NOT NULL,
  `justificatif` LONGBLOB NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

